rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/{document} {
      allow read, write: if false;
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/owned-a {
      allow get: if request.auth != null && request.auth.uid == resource.data.ownerUid;
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/owned-b {
      allow get: if request.auth != null && request.auth.uid == resource.data.ownerUid;
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/public-open {
      allow get: if request.auth == null;
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/claim-gated {
      allow get: if request.auth != null && request.auth.token.o5role == 'editor';
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/tenant-gated {
      allow get: if request.auth != null && request.auth.token.firebase.tenant == 'fireemu-00000000000000000001';
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/exists-guarded {
      allow get: if request.auth != null && exists(/databases/$(database)/documents/o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/exists-guard-present);
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/exists-guarded-missing {
      allow get: if request.auth != null && exists(/databases/$(database)/documents/o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/exists-guard-absent);
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/get-guarded {
      allow get: if request.auth != null && get(/databases/$(database)/documents/o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/owned-a).data.ownerUid == request.auth.uid;
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/getafter-target {
      allow create: if request.auth != null && getAfter(/databases/$(database)/documents/o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/getafter-guard).data.ownerUid == request.auth.uid;
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/getafter-control-target {
      allow create: if request.auth != null && getAfter(/databases/$(database)/documents/o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/getafter-control-guard).data.ownerUid == request.auth.uid;
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/getafter-guard {
      allow create: if request.auth != null && request.resource.data.ownerUid == request.auth.uid;
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/multiwrite-x {
      allow get, update: if request.auth != null && request.auth.uid == resource.data.ownerUid;
    }
    match /o5-user-token/n561bd55990a4428fab2c9db7237df47b/cases/multiwrite-y {
      allow create: if false;
    }
  }
}

